22	// renderChart draws a series as a sparkline of exactly `height` lines, each
23	// exactly `width` cells.
24	//
25	// The chart keeps **no** history at all: it is rebuilt every frame from the
26	// model's samples. That's what makes Rule 110 true by construction — there is
27	// no Push to place at the right spot — and it's what settles the rescaling
28	// problem: ntcharts.Resize rescales its own ring buffer, so a threshold change
29	// would truncate a history it owned. Here it's the model that owns it, and the
30	// chart is only a reading of it.
31	func renderChart(values []float64, width, height int, maxValue float64) []string {
32		if width < 1 || height < 1 {
33			return nil
34		}
35		if len(values) == 0 {
36			return blankLines(width, height)
37		}
38	
39		opts := []sparkline.Option{
40			// Draw() dresses the whole canvas, so the chart background also fills
41			// the gaps. DrawColumnsOnly() only colors the columns and lets the
42			// terminal's native background show through the holes — exactly what
43			// Rule 115 forbids.
44			sparkline.WithStyle(chartStyle()),
45		}
46		if maxValue > 0 {
47			// Fixed scale for a percentage: without it, an idle machine displays a
48			// chart as tall as a saturated machine, because the scale follows the
49			// observed maximum.
50			opts = append(opts, sparkline.WithMaxValue(maxValue), sparkline.WithNoAutoMaxValue())
51		}
52	
53		chart := sparkline.New(width, height, opts...)
54		chart.PushAll(trimToWidth(values, width, height))
55		if height >= brailleFrom {
56			chart.DrawBraille()
57		} else {
58			chart.Draw()
59		}
60	
61		lines := strings.Split(chart.View(), "\n")
62		for i, line := range lines {
63			lines[i] = padChart(line, width)
64		}
65		for len(lines) < height {
66			lines = append(lines, chartBlank(width))
67		}
68		return lines[:height]
69	}
