195		if o.selfSigned {
196			leaf, _ := mint(t, leafTmpl, nil, nil)
197			return &tls.ConnectionState{Version: version, PeerCertificates: []*x509.Certificate{leaf}}, x509.NewCertPool()
198		}
199	
200		root, rootKey := mint(t, caTemplate("test root"), nil, nil)
201		pool := x509.NewCertPool()
202		pool.AddCert(root)
203	
204		signerCert, signerKey := root, rootKey
205		var intermediate *x509.Certificate
206		if o.withIntermediate || o.omitIntermediate {
207			intermediate, signerKey = mint(t, caTemplate("test intermediate"), root, rootKey)
208			signerCert = intermediate
209		}
210	
211		leaf, _ := mint(t, leafTmpl, signerCert, signerKey)
212	
213		presented := []*x509.Certificate{leaf}
214		if o.withIntermediate && !o.omitIntermediate {
215			presented = append(presented, intermediate)
216		}
217		return &tls.ConnectionState{Version: version, PeerCertificates: presented}, pool
